  $('#workshopList').innerHTML = [...new Set(records.map(r => standardWorkshop(r.workshop,crosswalkMappings)).filter(Boolean))].map(v => `<option value="${escapeHTML(v)}">`).join('');
  $('#processList').innerHTML = [...new Set(records.map(r => r.process).filter(Boolean))].map(v => `<option value="${escapeHTML(v)}">`).join('');
