async function importFiles(files) {
  if(!canEdit())return toast("需 Editor 权限",true);
  files=[...files].filter(file=>/\.(csv|xlsx|pdf|pptx)$/i.test(file.name));const messages = [], imported = [], extractedImages=[];
  const hasDocument=files.some(file=>/\.(pdf|pptx)$/i.test(file.name));if(hasDocument&&cloud?.configured&&!cloud.token){toast('请先点击页头云端状态并完成登录，再导入 PDF / PPTX 原始文件',true);return;}
  for (const file of files) {
    try { const ext = file.name.split('.').pop().toLowerCase(),sourceName=file.webkitRelativePath||file.name; if (!adapters[ext]) throw new Error('暂不支持此文件类型'); const allowOCR=$('#ocrConsent').checked&&Boolean(cloud?.config.ocrEnabled),adapter=ext==='pdf'?async()=>parsePDFDocument(await file.arrayBuffer(),sourceName,{allowOCR,ocrProvider:allowOCR?new OCRProvider({endpoint:'/api/ocr',consent:true,accessToken:cloud?.token||''}):null}):adapters[ext],result = await adapter(file); for(const r of result.records){r.projectId=projectId;if(projectId!=='khayrat'&&r.id)r.id=`${projectId}:${r.id}`;}for(const i of result.images){i.projectId=projectId;if(projectId!=='khayrat'){i.imageId=`${projectId}:${i.imageId}`;if(i.relatedRecordId)i.relatedRecordId=`${projectId}:${i.relatedRecordId}`;}}imported.push(...result.records); extractedImages.push(...result.images); const detail=result.metadata?`，第 ${result.metadata.issueNumber} 期 ${result.metadata.periodStart}—${result.metadata.periodEnd}，车间 ${result.metadata.statusCount}、工程量 ${result.metadata.quantityCount}、机具 ${result.metadata.equipmentCount}、风险/物流 ${result.metadata.riskCount}`:'';messages.push(`${sourceName}: ${result.records.length} 条记录，${result.images.length} 张有效图片${detail}${result.diagnostics?.decorativeImages?`，已排除 ${result.diagnostics.decorativeImages} 张 Logo/装饰图`:''}${result.diagnostics?.warnings?.length?'，'+result.diagnostics.warnings.join(''):''}`); }
    catch (error) { messages.push(`${file.name}: 导入失败（${error.message}）`); }
  }
  const existingRecords=new Map(store.all().map(record=>[businessKey(record),record])),seen=new Set(),preview=imported.map(record=>{const key=businessKey(record),duplicate=existingRecords.has(key)||seen.has(key);seen.add(key);record.id=record.id||crypto.randomUUID();return {record,duplicate};});
  const newRecords=preview.filter(x=>!x.duplicate).map(x=>x.record);
  const importId=crypto.randomUUID();
  for(const record of newRecords)record.originalFileId=`${importId}/${record.sourceFile||record.source}`;
  const existingImages=new Set(evidenceStore.all().map(i=>i.imageId)),newImages=extractedImages.filter(i=>!existingImages.has(i.imageId));
  const uploadedAt=new Date().toISOString();for(const image of newImages){image.uploadedAt=image.uploadedAt||uploadedAt;const related=newRecords.find(r=>businessKey(r)===image.relatedRecordKey)||existingRecords.get(image.relatedRecordKey);if(related)image.relatedRecordId=related.id;}
  pendingImport={scopeVersion,importId,fileObjects:[...files],files:[...files].map(f=>f.webkitRelativePath||f.name),records:newRecords,images:newImages,messages,hasDocument,cloudSave:Boolean(cloud?.configured&&cloud.token),autoAnalyze:Boolean($('#analyzeAfterImport').checked&&cloud?.config.visionEnabled&&cloud?.token),hasErrors:messages.some(x=>x.includes('导入失败'))};
  $('#importSummary').textContent=`解析 ${imported.length} 条记录、${extractedImages.length} 张有效施工图片；${preview.filter(x=>x.duplicate).length} 条重复将跳过；${messages.filter(x=>x.includes('导入失败')).length} 个文件失败。${pendingImport.autoAnalyze?' 上传后将自动分析图片。':''}`;
  $('#importMessages').textContent=messages.join('\n');
  $('#confirmImport').disabled=pendingImport.hasErrors||(!imported.length&&!extractedImages.length);
  $('#importPreviewRows').innerHTML=preview.slice(0,100).map(({record,duplicate})=>`<tr><td>${escapeHTML(record.sourceFile||record.source)}${record.pageNumber?` · 第 ${record.pageNumber} 页`:''}<details><summary>来源原文</summary><p>${escapeHTML(record.sourceExcerpt||record.rawRecord||'')}</p><small>${record.needsReview?'原文字段异常：'+escapeHTML(record.reviewFields.join(', ')):'已识别明确字段；展示仍以原文为准'}</small></details></td><td>${record.date||'<span class="negative">未识别</span>'}</td><td>${escapeHTML(record.workshop||'未识别')} / ${escapeHTML(record.process||'未识别')}</td><td>${escapeHTML(record.status||'—')}</td><td><span class="tag ${duplicate?'warning':'good'}">${duplicate?'重复跳过':'新增'}</span></td></tr>`).join('')||'<tr><td colspan="5" class="mini-empty">没有可导入的结构化记录</td></tr>';$('#uploadProgress').hidden=true;$('#confirmImport').textContent='确认上传并导入';$('#importDialog').showModal();
}
